import datetime as dt
import json
import sys
from collections import Counter
from urllib.parse import urlencode

import requests

OWNER = "cli"
REPO = "cli"
START = dt.datetime(2024, 12, 1, 0, 0, 0, tzinfo=dt.timezone.utc)
END = dt.datetime(2024, 12, 31, 23, 59, 59, tzinfo=dt.timezone.utc)

SESSION = requests.Session()
SESSION.headers.update({"Accept": "application/vnd.github+json"})


def parse_dt(s):
    if s is None:
        return None
    # GitHub uses Zulu time
    return dt.datetime.strptime(s, "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=dt.timezone.utc)


def fetch_pulls_created_in_range():
    pulls = []
    page = 1
    while True:
        url = f"https://api.github.com/repos/{OWNER}/{REPO}/pulls"
        params = {
            "state": "all",
            "sort": "created",
            "direction": "desc",
            "per_page": 100,
            "page": page,
        }
        resp = SESSION.get(url, params=params, timeout=60)
        resp.raise_for_status()
        data = resp.json()
        if not data:
            break
        stop = False
        for pr in data:
            created = parse_dt(pr.get("created_at"))
            if created is None:
                continue
            if created < START:
                stop = True
                break
            if START <= created <= END:
                pulls.append(pr)
        if stop:
            break
        page += 1
    return pulls


def fetch_issues_created_in_range():
    issues = []
    page = 1
    while True:
        url = f"https://api.github.com/repos/{OWNER}/{REPO}/issues"
        params = {
            "state": "all",
            "sort": "created",
            "direction": "desc",
            "per_page": 100,
            "page": page,
        }
        resp = SESSION.get(url, params=params, timeout=60)
        resp.raise_for_status()
        data = resp.json()
        if not data:
            break
        stop = False
        for issue in data:
            created = parse_dt(issue.get("created_at"))
            if created is None:
                continue
            if created < START:
                stop = True
                break
            if "pull_request" in issue:
                continue
            if START <= created <= END:
                issues.append(issue)
        if stop:
            break
        page += 1
    return issues


pulls = fetch_pulls_created_in_range()
issues = fetch_issues_created_in_range()

# PR stats
pr_total = len(pulls)
merged_prs = []
closed_not_merged = 0
contrib_counts = Counter()

for pr in pulls:
    user = pr.get("user") or {}
    login = user.get("login")
    if login:
        contrib_counts[login] += 1
    merged_at = parse_dt(pr.get("merged_at"))
    if merged_at:
        merged_prs.append(pr)
    else:
        if pr.get("state") == "closed":
            closed_not_merged += 1

pr_merged = len(merged_prs)
pr_closed = closed_not_merged

if merged_prs:
    total_days = 0.0
    for pr in merged_prs:
        created = parse_dt(pr.get("created_at"))
        merged_at = parse_dt(pr.get("merged_at"))
        if not created or not merged_at:
            continue
        delta = merged_at - created
        total_days += delta.total_seconds() / 86400.0
    avg_merge_days = round(total_days / pr_merged, 1)
else:
    avg_merge_days = 0.0

if contrib_counts:
    top_contributor = sorted(contrib_counts.items(), key=lambda x: (-x[1], x[0]))[0][0]
else:
    top_contributor = ""

# Issue stats
issue_total = len(issues)

bug_issues = []
for issue in issues:
    labels = issue.get("labels") or []
    is_bug = any("bug" in (label.get("name", "").lower()) for label in labels)
    if is_bug:
        bug_issues.append(issue)

issue_bug = len(bug_issues)

resolved_bugs = 0
for issue in bug_issues:
    closed_at = parse_dt(issue.get("closed_at"))
    if closed_at and START <= closed_at <= END:
        resolved_bugs += 1

report = {
    "pr": {
        "total": pr_total,
        "merged": pr_merged,
        "closed": pr_closed,
        "avg_merge_days": avg_merge_days,
        "top_contributor": top_contributor,
    },
    "issue": {
        "total": issue_total,
        "bug": issue_bug,
        "resolved_bugs": resolved_bugs,
    },
}

with open("/app/report.json", "w", encoding="utf-8") as f:
    json.dump(report, f, indent=2, sort_keys=False)
    f.write("\n")

print(json.dumps(report, indent=2))
